// Unified Multi-Event Router for DueMitra ERP
const inputData = $input.first()?.json?.body || $input.first()?.json || {};
const eventType = inputData.event || 'due_reminders_digest';

// 1. Connection Ping Test Handler (From DueMitra Settings > Test Connection)
if (eventType === 'ping_test' || inputData.test === true || inputData.ping === true) {
  return [{
    json: {
      success: true,
      status: 'connected',
      event: 'ping_test',
      sendEmail: false,
      message: 'DueMitra n8n Webhook Live & Responsive',
      to: 'none',
      timestamp: new Date().toISOString()
    }
  }];
}

// 2. Customer Dispute or Payment Claim Handler
if (eventType === 'customer_dispute' || eventType === 'customer_already_paid') {
  return [{
    json: {
      success: true,
      status: eventType === 'customer_dispute' ? 'dispute_logged' : 'claim_logged',
      event: eventType,
      sendEmail: false,
      action: eventType === 'customer_dispute' ? 'Escalation Ladder Paused' : 'Bank Reconciliation Queued',
      invoiceNumber: inputData.data?.invoiceNumber || inputData.invoiceNumber,
      message: eventType === 'customer_dispute' ? 'Dispute recorded: escalation paused' : 'Claim received: bank verification queued',
      to: 'none',
      timestamp: new Date().toISOString()
    }
  }];
}

// 3. Email Dispatch (Digest or Invoice)
const businessName = inputData.businessName || 'Kavach Mobile Accessories';
const rawEmail = inputData.to || inputData.recipientEmail || inputData.email || '';
const recipientEmail = (rawEmail && !rawEmail.includes('kavachaccessories.in') && rawEmail.includes('@')) ? rawEmail.trim() : '';

// If pre-rendered HTML/Subject was passed from DueMitra app
if (inputData.html && inputData.subject) {
  return [{
    json: {
      to: recipientEmail,
      sendEmail: Boolean(recipientEmail),
      subject: inputData.subject,
      html: inputData.html,
      text: inputData.text || inputData.message,
      event: eventType,
      status: 'prepared_from_app',
      message: Boolean(recipientEmail) ? 'Prepared and queued for dispatch' : 'Digest processed (email skipped: no valid recipient)',
      timestamp: new Date().toISOString()
    }
  }];
}

// 4. Default / Autonomous Cron Fallback Data Structure
const followups = inputData.followups || [
  {
    invoiceNumber: 'KVC/26-27/0031',
    customerName: 'Sahyadri Telecom',
    customerPhone: '+91 98221 44556',
    balanceDuePaise: 2289200,
    balanceDueFormatted: '₹22,892',
    stageNumber: 3,
    stageName: 'Firmer Reminder',
    daysDiff: 5
  },
  {
    invoiceNumber: 'KVC/26-27/0026',
    customerName: 'Maratha Mobile World',
    customerPhone: '+91 98902 33441',
    balanceDuePaise: 3433800,
    balanceDueFormatted: '₹34,338',
    stageNumber: 4,
    stageName: 'Pre-Demand Notice',
    daysDiff: 29
  },
  {
    invoiceNumber: 'KVC/26-27/0023',
    customerName: 'Balaji Cellular Store',
    customerPhone: '+91 98500 22334',
    balanceDuePaise: 14750000,
    balanceDueFormatted: '₹1,47,500',
    stageNumber: 5,
    stageName: 'Payment Demand Letter',
    daysDiff: 80
  }
];

const totalOverdueFormatted = inputData.totalOverdueFormatted || '₹2,04,730';
const totalOutstandingFormatted = inputData.totalOutstandingFormatted || '₹4,82,892';

const subject = `🛡️ DueMitra Due Digest (Every 2-3h): ${totalOverdueFormatted} Overdue • ${followups.length} Reminders Due [${businessName}]`;

const rows = followups.map(f => `
  <tr>
    <td style="padding: 10px; border-bottom: 1px solid #1e293b; color: #ffffff; font-weight: bold;">${f.customerName}<br><span style="color: #94a3b8; font-size: 11px;">${f.customerPhone}</span></td>
    <td style="padding: 10px; border-bottom: 1px solid #1e293b; color: #cbd5e1; font-family: monospace;">${f.invoiceNumber}</td>
    <td style="padding: 10px; border-bottom: 1px solid #1e293b; color: #ffffff; font-weight: bold; text-align: right; font-family: monospace;">${f.balanceDueFormatted}</td>
    <td style="padding: 10px; border-bottom: 1px solid #1e293b; text-align: center;"><span style="background: #6366f1; color: #ffffff; padding: 2px 8px; border-radius: 9999px; font-size: 10px; font-weight: bold;">Stage ${f.stageNumber}: ${f.stageName}</span></td>
  </tr>
`).join('');

const html = `
<!DOCTYPE html>
<html>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background-color: #0a0f1d; color: #f8fafc; padding: 20px; margin: 0;">
  <div style="max-width: 640px; margin: 0 auto; background: #0f172a; border-radius: 14px; border: 1px solid rgba(255,255,255,0.1); overflow: hidden;">
    <div style="background: linear-gradient(135deg, #1e1b4b 0%, #0f172a 100%); padding: 24px; border-bottom: 1px solid rgba(255,255,255,0.08);">
      <h1 style="margin: 0; font-size: 20px; color: #ffffff;">🛡️ ${businessName} - Executive Due Digest</h1>
      <p style="margin: 4px 0 0; color: #94a3b8; font-size: 12px;">Autonomous 2-3 Hour Briefing &bull; n8n Cloud Engine</p>
    </div>
    <div style="padding: 20px; background: #0b1120;">
      <table style="width: 100%;">
        <tr>
          <td style="padding: 8px; background: #111c33; border-radius: 10px;">
            <span style="font-size: 10px; color: #94a3b8; text-transform: uppercase;">Total Outstanding</span>
            <div style="font-size: 18px; font-weight: bold; color: #ffffff;">${totalOutstandingFormatted}</div>
          </td>
          <td style="padding: 8px; background: #111c33; border-radius: 10px;">
            <span style="font-size: 10px; color: #f43f5e; text-transform: uppercase;">Capital Overdue</span>
            <div style="font-size: 18px; font-weight: bold; color: #f43f5e;">${totalOverdueFormatted}</div>
          </td>
          <td style="padding: 8px; background: #111c33; border-radius: 10px;">
            <span style="font-size: 10px; color: #10b981; text-transform: uppercase;">MSMED Rate</span>
            <div style="font-size: 18px; font-weight: bold; color: #10b981;">19.5% p.a.</div>
          </td>
        </tr>
      </table>
    </div>
    <div style="padding: 20px;">
      <h3 style="margin: 0 0 12px; font-size: 14px; color: #ffffff;">Follow-up Reminders Queue for Today</h3>
      <table style="width: 100%; border-collapse: collapse; font-size: 12px;">
        <thead>
          <tr style="background: rgba(255,255,255,0.04); color: #94a3b8;">
            <th style="padding: 8px;">Customer</th>
            <th style="padding: 8px;">Invoice</th>
            <th style="padding: 8px; text-align: right;">Due</th>
            <th style="padding: 8px; text-align: center;">Stage</th>
          </tr>
        </thead>
        <tbody>
          ${rows}
        </tbody>
      </table>
    </div>
    <div style="padding: 16px; background: #070b14; text-align: center; font-size: 11px; color: #64748b;">
      Generated automatically every 2-3 hours by DueMitra ERP & n8n Cloud
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    to: recipientEmail,
    sendEmail: Boolean(recipientEmail),
    subject,
    html,
    text: subject,
    event: eventType,
    status: 'digest_compiled',
    message: Boolean(recipientEmail) ? 'Digest compiled and queued for email delivery' : 'Digest compiled (email skipped: no valid recipient)',
    timestamp: new Date().toISOString()
  }
}];
